const numbers = [12, 45, 7, 89, 23, 56];

function findLargestLoop(numbers: array): int {
    let max = numbers[0];
    for (let i = 1; i < numbers.length; i++) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }
    return max;
}

print("12\n45\n7\n89\n23\n56\n");
print(findLargestLoop(numbers));
```

