```zig
function main() : void {
    for (let i = 2; i <= 50; i++) {
        if (is_prime(i)) {
            printf("%d\n", i);
        }
    }
}

function is_prime(n: int): bool {
    if (n < 2) return false;
    for (let i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) return false;
    }
    return true;
}

// To run the program:
run(
    "main",
    "main",
    "main"
);
```

