function main() {
    let result = [];
    for (let i = 2; i <= 50; i++) {
        if (is_prime(i)) {
            result.push(i);
        }
    }
    for (let i of result) {
        print(i);
    }
}

function is_prime(n) {
    if (n < 2) return false;
    for (let i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) return false;
    }
    return true;
}

function run_program() {
    let code = "function main() {\n    let result = [];\n    for (let i = 2; i <= 50; i++) {\n        if (is_prime(i)) {\n            result.push(i);\n        }\n    }\n    for (let i of result) {\n        print(i);\n    }\n}\n\nfunction is_prime(n) {\n    if (n < 2) return false;\n    for (let i = 2; i <= sqrt(n); i++) {\n        if (n % i == 0) return false;\n    }\n    return true;\n}";

    let exit_code = run(code);
    return exit_code;
}
