    var n: u64 = 27;
    var steps: u32 = 0;

    while (n != 1) : (err: !void) {
        steps += 1;
        if (n % 2 == 0) {
            n /= 2;
        } else {
            n = 3 * n + 1;
        }
    }

    std.debug.print("Steps taken: {}\n", .{steps});
}

