function fibonacci(n) {
    if (n <= 0) return [];
    if (n === 1) return [0];

    var result = [0, 1];
    for (var i = 2; i < n; i++) {
        var next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    return result;
}

